// Wallet-ID events read with their pre-run-66 address fields (audit 98cd2a781).
//
// Run 66 replaced `address indexed player` (and buyer/winner/owner/…) with the player's uint32
// wallet ID in most events, usually under a new name (`walletId`, `playerId`, `id`, …). Every
// chain projection was written against the address field. Rather than re-teaching each one, the
// event readers (facts.js eventFacts, event-store.js cachedEvents/previousEvents, client.events,
// feeds.js gameReceipt) pass decoded rows through decorateWalletRows(): it puts the resolved
// lowercase ADDRESS back under the field's pre-run-66 name, and keeps the ID under its new name
// (or `<name>Id` when the name did not change, e.g. `player` -> `player` + `playerId`).
//
// The field pairs are DERIVED, not hand-listed: an event present in both the frozen run-65 schema
// (5cd4b457) and the active one, at a position where the old input was `address`/`address[]` and
// the new one is `uint32`/`uint32[]`. Topic filters given under an old name with an address value
// are translated to the ID topic the same way (translateWalletFilters).
//
// On deployments before run 66 everything here is a no-op.
import { hasWalletIds, loadSchema } from './schema.js';
import * as beforeWalletIds from './schemas/5cd4b457/index.js';
import { walletIdOf, walletAddresses } from './wallets.js';

const specs = new Map(); // `${contract}` -> Promise<Map(eventName -> [{ index, legacy, current, idName, array }])>

async function contractSpecs(contract) {
  if (!specs.has(contract)) {
    specs.set(contract, (async () => {
      const out = new Map();
      let previous;
      try { previous = (await beforeWalletIds.loadSchema(contract)).abi; } catch { return out; }
      const current = (await loadSchema(contract)).abi;
      for (const event of current) {
        if (event.type !== 'event') continue;
        const old = previous.find(item => item.type === 'event' && item.name === event.name);
        if (!old) continue;
        const pairs = [];
        event.inputs.forEach((input, index) => {
          const before = old.inputs[index];
          if (!before) return;
          const array = /\[\]$/.test(input.type);
          if (!/^address(\[\])?$/.test(before.type) || input.type !== (array ? 'uint32[]' : 'uint32')) return;
          if (/\[\]$/.test(before.type) !== array) return;
          const legacy = before.name; const currentName = input.name;
          pairs.push({ index, legacy, current: currentName, idName: currentName === legacy ? `${legacy}Id` : currentName, array });
        });
        if (pairs.length) out.set(event.name, pairs);
      }
      if (contract === 'WWXRP') out.set('PrizeCredited', [{index:0, legacy:'player', current:'id', idName:'id', array:false}]);
      return out;
    })());
  }
  return specs.get(contract);
}

/** The address<->ID field pairs of `contract.eventName` on the active deployment ([] before run 66). */
export async function walletFieldPairs(contract, eventName) {
  if (!hasWalletIds()) return [];
  return (await contractSpecs(contract)).get(eventName) ?? [];
}

/** Rebuild an ethers Result (or plain args) with extra named, non-positional fields. */
function withNamed(args, extra) {
  if (!args || typeof args !== 'object') return args;
  if (!Array.isArray(args) && typeof args.toArray !== 'function') return { ...args, ...extra };
  const positional = Array.from(args);
  const named = typeof args.toObject === 'function' ? (() => { try { return args.toObject(); } catch { return {}; } })() : {};
  Object.assign(named, extra);
  const out = positional.slice();
  for (const [name, value] of Object.entries(named)) {
    if (/^\d+$/.test(name)) continue;
    Object.defineProperty(out, name, { value, enumerable: false, configurable: true });
  }
  Object.defineProperty(out, 'toObject', { value: () => ({ ...named }), enumerable: false });
  return out;
}

/**
 * Add each ID field's address under its pre-run-66 name. `rows` are `{ name, args }` (decoded
 * logs or facts rows); `contract` is the source contract key, or a function row -> key when the
 * rows come from several contracts. Returns new rows; the input is not mutated.
 */
export async function decorateWalletRows(s, contract, rows) {
  if (!hasWalletIds() || !rows?.length) return rows;
  const plans = await Promise.all(rows.map(async row => {
    const source = typeof contract === 'function' ? contract(row) : contract;
    return source && row?.name ? walletFieldPairs(source, row.name) : [];
  }));
  const ids = new Set();
  rows.forEach((row, i) => {
    for (const pair of plans[i]) {
      const value = readArg(row.args, pair);
      for (const id of [].concat(value ?? [])) ids.add(Number(id));
    }
  });
  if (!ids.size) return rows;
  const addresses = await walletAddresses(s, ids);
  const lookup = id => addresses.get(Number(id)) ?? null;
  return rows.map((row, i) => {
    if (!plans[i].length) return row;
    const extra = {};
    for (const pair of plans[i]) {
      const value = readArg(row.args, pair);
      // The ID keeps the row's own representation (a string in plain fact rows, a bigint in a
      // decoded Result); only a same-named field needs the copy under `<name>Id`.
      if (pair.idName !== pair.current || pair.current === pair.legacy) extra[pair.idName] = value;
      if (pair.array) extra[pair.legacy] = [...(value ?? [])].map(id => (Number(id) ? lookup(id) : ZERO));
      else extra[pair.legacy] = value == null ? null : (Number(value) ? lookup(value) : ZERO);
    }
    return { ...row, args: withNamed(row.args, extra) };
  });
}
const ZERO = '0x0000000000000000000000000000000000000000';

function readArg(args, pair) {
  if (args == null) return null;
  // Plain fact rows carry the new field by name; Results also answer positionally.
  const named = args[pair.current];
  if (named != null) return named;
  return Array.isArray(args) || typeof args?.toArray === 'function' ? args[pair.index] : null;
}

/**
 * Translate topic filters written with pre-run-66 names/addresses: `{ player: '0xabc…' }` becomes
 * `{ walletId: 42 }`. Returns null when an address filter names a wallet with no ID (nothing can
 * match). Filters on fields that are still addresses pass through unchanged.
 */
export async function translateWalletFilters(s, contract, eventName, filters = {}) {
  const pairs = await walletFieldPairs(contract, eventName);
  if (!pairs.length || !filters) return filters;
  const out = { ...filters };
  for (const pair of pairs) {
    const key = pair.legacy in out ? pair.legacy : null;
    if (key == null) continue;
    const value = out[key];
    if (value == null) continue;
    const values = Array.isArray(value) ? value : [value];
    const translated = [];
    for (const item of values) {
      if (typeof item === 'string' && /^0x[0-9a-f]{40}$/i.test(item)) {
        const id = await walletIdOf(s, item);
        if (id) translated.push(id);
      } else translated.push(item);
    }
    if (pair.current !== key) delete out[key];
    if (!translated.length) return null;
    out[pair.current] = Array.isArray(value) ? translated : translated[0];
  }
  return out;
}
